INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(92180, 0, 0, 'Hah!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66683'),
(92180, 1, 0, 'Haz\'gorg isn\'t strong enough to lead the Maul\'ogg, I will do as I please, I am strongest, you are lucky to live after such words little $R.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67027'),
(92180, 2, 0, 'A potion of strength?! Haz\'gorg has learned his place, hah!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66385'),
(92180, 3, 0, 'I can feel it, yes, through my body! I... Hmm... I feel funny, and good. Tell Haz\'gorg that I thank him for the potion, I have thought over what he said earlier, maybe Maul\'ogg rest and think about strategy to expand, rather then smash enemy.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66475'),
(92191, 0, 0, 'Now, behold my brilliance, my sheer wit and power of mind! With these items, I will be rich again! Haha!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66665'),
(92191, 1, 0, 'Huh... Maybe its supposed to take a while, I\'ll think of a new method to make this work, thanks again pal!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66666'),
(92144, 0, 0, 'We got company on the ship! Push back these mainlanders!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66400'),
(60446, 0, 0, 'I come from a land far away, shrouded in mystery and green mist. I am blessed by those you would not understand, and those that inhabit this mystical land. I am an outcast of my kin, and have only come here to seek new purpose. This purpose was found upon these islands.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66405'),
(60446, 1, 0, 'Slowly, day by day, a darkness came, a power much like myself that dared to challenge the rule I had established. Little by little I would lose this pitiful match of displaying power to attempt to keep the locals swayed to my side.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66406'),
(60446, 2, 0, 'In the end, I could not offer the secrets of my power to those that followed me. Eventually, most of my followers and worshippers stepped aside to bask in the glory of this dark energy. Now, I am seeking revenge, I am seeking to once again reclaim my throne upon these lands, do you understand mortal?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66407'),
(60446, 3, 0, 'There, it is done. The key is attuned. Do with it what you must. I hope that it serves you well for whatever purpose you are using it.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66672'),
(60446, 4, 0, 'We must travel to the center of Kazon Island, there, I can channel the energies of both Lapidis, and Gillijim.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66409'),
(60446, 5, 0, 'With the energies, and my own, I will be able to draw out the corruption that has plagued the land.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66410'),
(60446, 6, 0, 'Now then - this will take much concentration to bring the entity forward into physical form, it is up to you to weaken it! When it is weak enough, I will be free to join you, until then, protect me!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66411'),
(60446, 7, 0, 'Come, $n. It is time to banish this evil.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle C++ literal text'),
(60446, 8, 0, 'I must confess something to you mortal, for I am not one to withhold information, nor am I one to outwardly lie without purpose. I had many reasonings for the death of the Prophet Jammal\'an within the depths of the Sunken Temple.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66673'),
(92137, 0, 0, 'Fine! Spare me please, here is the recipe!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66653');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9092180, 'I am Lord Cruk\'zogg, I lead here. We were once part of the great Gor\'dosh tribe, but now we are alone.\n\nYou will help me recreate the glory of Maul\'ogg!', 'I am Lord Cruk\'zogg, I lead here. We were once part of the great Gor\'dosh tribe, but now we are alone.\n\nYou will help me recreate the glory of Maul\'ogg!', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9092180, 9092180);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9092180, 0, 0, 'Lord Cruk\'Zogg, I come on behalf of Haz\'gorg, he is asking you to end your foolhardy aggresion.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
