INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9092180, 1, 0, 'Lord Cruk\'zogg, Haz\'gorg has asked me to deliver this potion of strength to help enhance your mighty power!', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
